{
  "mechanisms": [
    {
      "name": "mb_mf_mixture",
      "title": "MB/MF mixture weight",
      "description": "A weighting parameter that combines model-based and model-free stage-1 action values.",
      "params": [
        {
          "name": "w",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_net = w * q_stage1_mb + (1.0 - w) * q_stage1_mf",
      "expressible_in_slots": true
    },
    {
      "name": "separate_betas",
      "title": "Separate stage inverse temperatures",
      "description": "Distinct inverse temperature parameters for stage-1 and stage-2 choices.",
      "params": [
        {
          "name": "beta1",
          "bounds": [0, 10]
        },
        {
          "name": "beta2",
          "bounds": [0, 10]
        }
      ],
      "evidence": "logits_1 = beta1 * q_net\n...\nlogits_2 = beta2 * q_stage2_mf[s]",
      "expressible_in_slots": true
    },
    {
      "name": "eligibility_trace",
      "title": "Eligibility trace",
      "description": "An eligibility trace parameter that allows stage-2 reward prediction errors to update stage-1 model-free values.",
      "params": [
        {
          "name": "lam",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_stage1_mf[a1] += alpha * delta_stage1 + alpha * lam * delta_stage2",
      "expressible_in_slots": true
    },
    {
      "name": "value_decay",
      "title": "Value decay for unchosen actions",
      "description": "Unchosen actions at both stages decay towards a neutral expected value of 0.5 over time.",
      "params": [
        {
          "name": "decay",
          "bounds": [0, 1]
        }
      ],
      "evidence": "unchosen_a1 = 1 - a1\n        q_stage1_mf[unchosen_a1] = (1.0 - decay) * q_stage1_mf[unchosen_a1] + decay * 0.5\n        \n        for state_idx in range(2):\n            for action_idx in range(2):\n                if not (state_idx == s and action_idx == a2):\n                    q_stage2_mf[state_idx, action_idx] = (1.0 - decay) * q_stage2_mf[state_idx, action_idx] + decay * 0.5",
      "expressible_in_slots": true
    },
    {
      "name": "neutral_q_init",
      "title": "Neutral Q initialization",
      "description": "Action values are initialized to 0.5 instead of 0.",
      "params": [],
      "evidence": "q_stage1_mf = np.ones(2) * 0.5\n    q_stage2_mf = np.ones((2, 2)) * 0.5",
      "expressible_in_slots": true
    }
  ]
}
